sys_script_include.script:
var ApolloAppointmentValidator = Class.create();
ApolloAppointmentValidator.prototype = {
    initialize: function() {},

    /**
     * Checks if the appointment overlaps with existing active appointments for the Doctor or Patient.
     * Overlap condition: (existing.start_time < new.end_time) AND (existing.end_time > new.start_time)
     * 
     * @param {GlideRecord} current - The appointment being inserted or updated
     * @returns {Object} { valid: Boolean, message: String }
     */
    validateAndLock: function(current) {
        var doctor = current.getValue('doctor');
        var patient = current.getValue('patient');
        var start = current.getValue('start_time');
        var end = current.getValue('end_time');
        var currentId = current.getUniqueValue();
        var status = current.getValue('status');

        // Inactive / non-blocking statuses: 6 (Completed), 7 (Cancelled), 8 (No Show), 9 (Rescheduled)
        var inactiveList = ['6', '7', '8', '9', 'completed', 'cancelled', 'rescheduled', 'no_show', 'no show'];

        // If the appointment itself is inactive or being set to inactive, allow it immediately (frees the slot)
        if (status && inactiveList.indexOf(String(status).toLowerCase()) !== -1) {
            return { valid: true };
        }

        // Mandatory values check
        if (!doctor || !patient || !start || !end) {
            return { valid: true };
        }

        // 1. DOCTOR OVERLAP CHECK
        var docGr = new GlideRecord('x_2223823_apollo_0_appointment');
        docGr.addQuery('doctor', doctor);
        if (currentId) {
            docGr.addQuery('sys_id', '!=', currentId);
        }
        // Exclude inactive appointments
        docGr.addQuery('status', 'NOT IN', '6,7,8,9,completed,cancelled,rescheduled,no_show');
        // Overlap formula: existing.start < new.end AND existing.end > new.start
        docGr.addQuery('start_time', '<', end);
        docGr.addQuery('end_time', '>', start);
        docGr.setLimit(1);
        docGr.query();

        if (docGr.next()) {
            return {
                valid: false,
                message: 'This doctor already has an appointment during the selected time.'
            };
        }

        // 2. PATIENT OVERLAP CHECK
        var patGr = new GlideRecord('x_2223823_apollo_0_appointment');
        patGr.addQuery('patient', patient);
        if (currentId) {
            patGr.addQuery('sys_id', '!=', currentId);
        }
        patGr.addQuery('status', 'NOT IN', '6,7,8,9,completed,cancelled,rescheduled,no_show');
        // Overlap formula: existing.start < new.end AND existing.end > new.start
        patGr.addQuery('start_time', '<', end);
        patGr.addQuery('end_time', '>', start);
        patGr.setLimit(1);
        patGr.query();

        if (patGr.next()) {
            return {
                valid: false,
                message: 'You already have another appointment scheduled during this time.'
            };
        }

        // No conflict found
        return { valid: true };
    },

    type: 'ApolloAppointmentValidator'
};
